 "model": {
  "variables": [
   {
    "name": "tonometer tests",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "puff of air tests",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "tonometer tests",
     "coef": 1.0
    },
    {
     "var": "puff of air tests",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "office hours",
    "terms": [
     {
      "var": "tonometer tests",
